const __aivicBundle_57_aggregateDailyReportsWithTimestampSort = (() => {
  function aggregateDailyReportsWithTimestampSort(
    reports: Array<{
      user_id?: string;
      employee_id?: string;
      user_name?: string;
      employee_name?: string;
      yesterday_achievement?: string;
      today_plan?: string;
      issues?: string;
      issue?: string;
      submitted_at: Date;
    }>,
  ): Array<{
    user_id?: string;
    employee_id?: string;
    user_name?: string;
    employee_name?: string;
    yesterday_achievement?: string;
    today_plan?: string;
    issues?: string;
    issue?: string;
    submitted_at: Date;
  }> {
    if (!reports || reports.length === 0) {
      return [];
    }
  
    const seenUserIds = new Set<string>();
    const deduplicatedReports: Array<{
      user_id?: string;
      employee_id?: string;
      user_name?: string;
      employee_name?: string;
      yesterday_achievement?: string;
      today_plan?: string;
      issues?: string;
      issue?: string;
      submitted_at: Date;
    }> = [];
  
    for (const report of reports) {
      const userId = report.user_id || report.employee_id;
      if (userId && !seenUserIds.has(userId)) {
        seenUserIds.add(userId);
        deduplicatedReports.push(report);
      } else if (!userId) {
        deduplicatedReports.push(report);
      }
    }
  
    const sortedReports = deduplicatedReports.sort((a, b) => {
      return a.submitted_at.getTime() - b.submitted_at.getTime();
    });
  
    return sortedReports;
  }
  return { aggregateDailyReportsWithTimestampSort };
})();
